const c = msg.metadata.source.client_specific;
const LIMIT = 50;

msg.url = c.base_url + "/cases?limit=" + LIMIT;
msg.headers = { "Authorization": "Bearer " + c.api_key };
return msg;

// CIM returns { cases: [...] }. Sort oldest-first so the cursor advances correctly.
const cases = (msg.payload && msg.payload.cases) ? msg.payload.cases.slice() : [];
if (cases.length === 0) return null;

const parse = global.get("utils").parse_cim_timestamp;
cases.sort((a, b) => parse(a.global.case_created) - parse(b.global.case_created));

msg.payload = cases;
return msg;

const cursor_ts  = msg.metadata.source.timestamp;
const utils      = global.get("utils");
const connection = msg.metadata.connection_name;
const source_id  = msg.metadata.source.identifier;

msg.payload = msg.payload.filter(c => {
    const reg = c.registration || {};
    const g   = c.global || {};
    const ts  = utils.parse_cim_timestamp(g.case_created);
    if (cursor_ts && ts <= cursor_ts) return false;
    if (reg.subject     && utils.is_bridge_message(reg.subject))     return false;
    if (reg.description && utils.is_bridge_message(reg.description)) return false;
    if (g.case_created_by && utils.is_bridge_message(g.case_created_by)) return false;
    return true;
});

if (msg.payload.length === 0) return null;

// Cursor advance \u2014 last case is newest (sorted ascending in previous step).
const last_ts = utils.parse_cim_timestamp(msg.payload[msg.payload.length - 1].global.case_created);
global.set(
    `parat_bridge.connections.${connection}.clients.${source_id}.timestamp`,
    last_ts
);
return msg;
